package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
)

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user
func CreateUser(u User) (User, error) {
	mutex.Lock()
	defer mutex.Unlock()

	u.ID = uuid.New().String()
	users[u.ID] = u
	return u, nil
}

// GetUserByID retrieves a user by their ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	u, ok := users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"rep-7/internal/service"
)

// GetUsersHandler handles the request to get all users
func GetUsersHandler(w http.ResponseWriter, r *http.Request) {
	list := service.GetAllUsers()
	json.NewEncoder(w).Encode(list)
}

// CreateUserHandler handles the request to create a new user
func CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := service.CreateUser(u)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByIDHandler handles the request to get a user by ID
func GetUserByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")
	u, ok := service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"rep-7/internal/api"
)

func main() {
	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.GetUsersHandler(w, r)
		case http.MethodPost:
			api.CreateUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.GetUserByIDHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"
)

func TestCreateAndGetUser(t *testing.T) {
	// Clear users map for a clean test environment
	users = make(map[string]User)

	user1 := User{Name: "Alice", Email: "alice@example.com"}
	createdUser1, err := CreateUser(user1)
	if err != nil {
		t.Fatalf("Error creating user 1: %v", err)
	}

	user2 := User{Name: "Bob", Email: "bob@example.com"}
	createdUser2, err := CreateUser(user2)
	if err != nil {
		t.Fatalf("Error creating user 2: %v", err)
	}

	if createdUser1.ID == createdUser2.ID {
		t.Errorf("Expected different IDs for created users, but got %s", createdUser1.ID)
	}

	retrievedUser1, ok := GetUserByID(createdUser1.ID)
	if !ok {
		t.Errorf("User with ID %s not found", createdUser1.ID)
	}

	if retrievedUser1.Name != user1.Name || retrievedUser1.Email != user1.Email {
		t.Errorf("Retrieved user 1 mismatch: expected %+v, got %+v", user1, retrievedUser1)
	}

	retrievedUser2, ok := GetUserByID(createdUser2.ID)
	if !ok {
		t.Errorf("User with ID %s not found", createdUser2.ID)
	}

	if retrievedUser2.Name != user2.Name || retrievedUser2.Email != user2.Email {
		t.Errorf("Retrieved user 2 mismatch: expected %+v, got %+v", user2, retrievedUser2)
	}

	_, ok = GetUserByID("nonexistent-id")
	if ok {
		t.Error("Expected no user for a nonexistent ID, but found one")
	}
}

func TestGetAllUsers(t *testing.T) {
	// Clear users map for a clean test environment
	users = make(map[string]User)

	list := GetAllUsers()
	if len(list) != 0 {
		t.Errorf("Expected empty list, got %d users", len(list))
	}

	user1 := User{Name: "Alice", Email: "alice@example.com"}
	CreateUser(user1)
	user2 := User{Name: "Bob", Email: "bob@example.com"}
	CreateUser(user2)

	list = GetAllUsers()
	if len(list) != 2 {
		t.Errorf("Expected 2 users, got %d users", len(list))
	}

	foundAlice := false
	foundBob := false
	for _, u := range list {
		if u.Name == "Alice" {
			foundAlice = true
		}
		if u.Name == "Bob" {
			foundBob = true
		}
	}

	if !foundAlice || !foundBob {
		t.Errorf("Expected to find Alice and Bob in the list, but didn't: %+v", list)
	}
}
